  var ACI = {}; ACI[BLEU]=5; ACI[ROUGE]=1; ACI[VERT]=3; ACI[ORANGE]=30; ACI["#2563EB"]=5; ACI["#DC2626"]=1; ACI["#92400E"]=34;
  var GROUPES = ["Éclairage","Prises","Commandes","Sécurité","Courants faibles","Chauffage et VMC","Ventilation et climatisation","Plomberie et chauffage","Divers"];
  var CALQUES = {"Éclairage":"ELEC-ECLAIRAGE", "Prises":"ELEC-PRISES", "Commandes":"ELEC-COMMANDES",
    "Sécurité":"ELEC-SECURITE", "Courants faibles":"ELEC-COURANTS-FAIBLES", "Chauffage et VMC":"ELEC-CHAUFFAGE-VMC", "Ventilation et climatisation":"CVC-VENTILATION-CLIM", "Plomberie et chauffage":"PLOMBERIE", "Divers":"ELEC-DIVERS"};
  /* l'index AutoCAD le plus proche d'une couleur (« trait » : 7, blanc ou noir selon le fond du logiciel) */
